CREATE TYPE "Role" AS ENUM ('USER', 'ADMIN');
CREATE TYPE "MovieStatus" AS ENUM ('NOW_SHOWING', 'UPCOMING', 'ARCHIVED');
CREATE TYPE "SeatStatus" AS ENUM ('AVAILABLE', 'HELD', 'BOOKED');
CREATE TYPE "ReservationStatus" AS ENUM ('ACTIVE', 'EXPIRED', 'CONFIRMED', 'CANCELLED');
CREATE TYPE "BookingStatus" AS ENUM ('CONFIRMED', 'CANCELLED');
CREATE TYPE "PaymentStatus" AS ENUM ('SUCCEEDED', 'REFUNDED');

CREATE TABLE "User" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "role" "Role" NOT NULL DEFAULT 'USER', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Movie" ("id" TEXT PRIMARY KEY, "title" TEXT NOT NULL, "slug" TEXT NOT NULL, "synopsis" TEXT NOT NULL, "genre" TEXT NOT NULL, "duration" INTEGER NOT NULL, "rating" TEXT NOT NULL, "score" DOUBLE PRECISION NOT NULL, "posterUrl" TEXT NOT NULL, "backdropUrl" TEXT NOT NULL, "releaseDate" TIMESTAMP(3) NOT NULL, "status" "MovieStatus" NOT NULL DEFAULT 'NOW_SHOWING', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Auditorium" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Seat" ("id" TEXT PRIMARY KEY, "auditoriumId" TEXT NOT NULL, "row" TEXT NOT NULL, "number" INTEGER NOT NULL);
CREATE TABLE "Showtime" ("id" TEXT PRIMARY KEY, "movieId" TEXT NOT NULL, "auditoriumId" TEXT NOT NULL, "startsAt" TIMESTAMP(3) NOT NULL, "price" DECIMAL(10,2) NOT NULL);
CREATE TABLE "Reservation" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL, "showtimeId" TEXT NOT NULL, "status" "ReservationStatus" NOT NULL DEFAULT 'ACTIVE', "expiresAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ShowtimeSeat" ("id" TEXT PRIMARY KEY, "showtimeId" TEXT NOT NULL, "seatId" TEXT NOT NULL, "status" "SeatStatus" NOT NULL DEFAULT 'AVAILABLE', "reservationId" TEXT, "holdExpiresAt" TIMESTAMP(3), "version" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "Booking" ("id" TEXT PRIMARY KEY, "reference" TEXT NOT NULL, "userId" TEXT NOT NULL, "showtimeId" TEXT NOT NULL, "reservationId" TEXT NOT NULL, "status" "BookingStatus" NOT NULL DEFAULT 'CONFIRMED', "total" DECIMAL(10,2) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "cancelledAt" TIMESTAMP(3));
CREATE TABLE "BookingItem" ("id" TEXT PRIMARY KEY, "bookingId" TEXT NOT NULL, "showtimeSeatId" TEXT NOT NULL, "price" DECIMAL(10,2) NOT NULL);
CREATE TABLE "Payment" ("id" TEXT PRIMARY KEY, "bookingId" TEXT NOT NULL, "amount" DECIMAL(10,2) NOT NULL, "status" "PaymentStatus" NOT NULL DEFAULT 'SUCCEEDED', "provider" TEXT NOT NULL DEFAULT 'SIMULATED', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE UNIQUE INDEX "Movie_slug_key" ON "Movie"("slug");
CREATE UNIQUE INDEX "Auditorium_name_key" ON "Auditorium"("name");
CREATE UNIQUE INDEX "Seat_auditoriumId_row_number_key" ON "Seat"("auditoriumId","row","number");
CREATE UNIQUE INDEX "Showtime_auditoriumId_startsAt_key" ON "Showtime"("auditoriumId","startsAt");
CREATE INDEX "Showtime_movieId_startsAt_idx" ON "Showtime"("movieId","startsAt");
CREATE UNIQUE INDEX "ShowtimeSeat_showtimeId_seatId_key" ON "ShowtimeSeat"("showtimeId","seatId");
CREATE INDEX "ShowtimeSeat_showtimeId_status_idx" ON "ShowtimeSeat"("showtimeId","status");
CREATE INDEX "ShowtimeSeat_status_holdExpiresAt_idx" ON "ShowtimeSeat"("status","holdExpiresAt");
CREATE INDEX "Reservation_userId_status_idx" ON "Reservation"("userId","status");
CREATE INDEX "Reservation_status_expiresAt_idx" ON "Reservation"("status","expiresAt");
CREATE UNIQUE INDEX "Booking_reference_key" ON "Booking"("reference");
CREATE UNIQUE INDEX "Booking_reservationId_key" ON "Booking"("reservationId");
CREATE INDEX "Booking_userId_createdAt_idx" ON "Booking"("userId","createdAt");
CREATE INDEX "BookingItem_showtimeSeatId_idx" ON "BookingItem"("showtimeSeatId");
CREATE UNIQUE INDEX "Payment_bookingId_key" ON "Payment"("bookingId");

ALTER TABLE "Seat" ADD CONSTRAINT "Seat_auditoriumId_fkey" FOREIGN KEY ("auditoriumId") REFERENCES "Auditorium"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Showtime" ADD CONSTRAINT "Showtime_movieId_fkey" FOREIGN KEY ("movieId") REFERENCES "Movie"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Showtime" ADD CONSTRAINT "Showtime_auditoriumId_fkey" FOREIGN KEY ("auditoriumId") REFERENCES "Auditorium"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Reservation" ADD CONSTRAINT "Reservation_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Reservation" ADD CONSTRAINT "Reservation_showtimeId_fkey" FOREIGN KEY ("showtimeId") REFERENCES "Showtime"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ShowtimeSeat" ADD CONSTRAINT "ShowtimeSeat_showtimeId_fkey" FOREIGN KEY ("showtimeId") REFERENCES "Showtime"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ShowtimeSeat" ADD CONSTRAINT "ShowtimeSeat_seatId_fkey" FOREIGN KEY ("seatId") REFERENCES "Seat"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ShowtimeSeat" ADD CONSTRAINT "ShowtimeSeat_reservationId_fkey" FOREIGN KEY ("reservationId") REFERENCES "Reservation"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Booking" ADD CONSTRAINT "Booking_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Booking" ADD CONSTRAINT "Booking_showtimeId_fkey" FOREIGN KEY ("showtimeId") REFERENCES "Showtime"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Booking" ADD CONSTRAINT "Booking_reservationId_fkey" FOREIGN KEY ("reservationId") REFERENCES "Reservation"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "BookingItem" ADD CONSTRAINT "BookingItem_bookingId_fkey" FOREIGN KEY ("bookingId") REFERENCES "Booking"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "BookingItem" ADD CONSTRAINT "BookingItem_showtimeSeatId_fkey" FOREIGN KEY ("showtimeSeatId") REFERENCES "ShowtimeSeat"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Payment" ADD CONSTRAINT "Payment_bookingId_fkey" FOREIGN KEY ("bookingId") REFERENCES "Booking"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
